const emptyDeletions=()=>({schema:REMOVAL_SCHEMA,version:1,layouts:[],images:[]});
function normalizedUrl(u){try{const url=new URL(String(u||''));if(!/^https?:$/.test(url.protocol))return '';url.hash='';return url.href.replace(/\/$/,'')}catch(_){return ''}}
function asTombstone(v,kind){if(!v||typeof v!=='object')return null;const id=String(v.id??'').slice(0,128);const sourceUrl=normalizedUrl(v.sourceUrl||v.source||v.license||v.filePageUrl);const wallpaperUrl=normalizedUrl(v.wallpaperUrl||v.wallpaper||v.url||v.imageUrl);const thumbnailUrl=normalizedUrl(v.thumbnailUrl||v.thumbnail);if(!id&&!sourceUrl&&!wallpaperUrl)return null;return {id,title:String(v.title||'').slice(0,200),category:String(v.category||'').slice(0,100),subcategory:String(v.subcategory||'').slice(0,120),sourceUrl,wallpaperUrl,thumbnailUrl}}
function mergeDeletions(base,incoming){const result=emptyDeletions();for(const kind of ['layouts','images']){const seen=new Set();for(const document of [base,incoming])for(const x of Array.isArray(document?.[kind])?document[kind]:[]){const item=asTombstone(x,kind);if(!item)continue;const marker=item.sourceUrl||item.wallpaperUrl||item.id;if(seen.has(marker))continue;seen.add(marker);result[kind].push(item)}}return result}
let removedRegistry=mergeDeletions(DELETED_INITIAL,(()=>{try{return JSON.parse(localStorage.getItem(DELETED_STORE)||'null')}catch(_){return null}})());
function isRemoved(kind,item){const id=String(item?.id??''),urls=new Set([item?.sourceUrl,item?.source,item?.filePageUrl,item?.license,item?.wallpaperUrl,item?.wallpaper,item?.url,item?.imageUrl,item?.thumbnailUrl,item?.thumbnail].map(normalizedUrl).filter(Boolean));return removedRegistry[kind]?.some(x=>{if(id&&id===String(x.id))return true;const identity=[x.sourceUrl,x.thumbnailUrl].map(normalizedUrl).filter(Boolean);if(kind==='layouts'&&id){const direct=new Set([item?.sourceUrl,item?.source,item?.thumbnailUrl,item?.thumbnail].map(normalizedUrl).filter(Boolean));return identity.some(v=>direct.has(v));}return [...identity,x.wallpaperUrl].filter(Boolean).some(v=>urls.has(normalizedUrl(v)));})||false}
function sanitizeAgainstDeletions(raw){if(!raw||typeof raw!=='object')return raw;
 if(raw.galleryApplied&&isRemoved('layouts',{id:String(raw.galleryApplied)}))raw.galleryApplied='';
 if(raw.styles&&typeof raw.styles==='object')for(const s of Object.values(raw.styles)){if(s&&typeof s==='object'&&s.image&&(isRemoved('images',{url:s.image})||isRemoved('layouts',{wallpaper:s.image}))){s.image='';s.pattern='none';s.overlayOpacity=0}}
 if(Array.isArray(raw.presets))for(const p of raw.presets)if(p?.data&&typeof p.data==='object')sanitizeAgainstDeletions(p.data);
 return raw}
function persistDeletions(){try{localStorage.setItem(DELETED_STORE,JSON.stringify(removedRegistry))}catch(_){notify('Deletion registry could not be saved to this browser. Export deleted.json.',true)}}
function catalogCount(){return {layouts:GALLERY_CATALOG.length,images:IMAGE_LIBRARY.length}}
function refreshCatalogGuards(){GALLERY_CATALOG.splice(0,GALLERY_CATALOG.length,...RAW_GALLERY_CATALOG.filter(x=>!isRemoved('layouts',x)));IMAGE_LIBRARY.splice(0,IMAGE_LIBRARY.length,...RAW_IMAGE_LIBRARY.filter(x=>!isRemoved('images',x)));
 const current=state?.galleryApplied||'';const oldStyles=JSON.stringify(state?.styles||{});sanitizeAgainstDeletions(state);if(current!==state.galleryApplied||oldStyles!==JSON.stringify(state.styles))persist();
 try{for(let ix=0;ix<localStorage.length;ix++){const key=localStorage.key(ix);if(!key||!key.startsWith('ourspace.design.v2.'))continue;try{const original=localStorage.getItem(key);const parsed=JSON.parse(original);sanitizeAgainstDeletions(parsed);if(JSON.stringify(parsed)!==original)localStorage.setItem(key,JSON.stringify(parsed))}catch(_){}}}catch(_){/* Storage unavailable; still export the removal list. */}
 apply();if(currentTab==='gallery')renderGallery();if(currentTab==='images')renderImages();
}
// Loading a physical deleted.json also protects catalogs in later app rebuilds.
if(location.protocol==='https:'||location.protocol==='http:'){
 const tombstoneFile=contextPage==='standalone'?'../../json/deleted.json':'../../json/deleted.json';
 fetch(tombstoneFile,{cache:'no-store'}).then(r=>r.ok?r.json():null).then(d=>{if(d?.schema!==REMOVAL_SCHEMA)return;removedRegistry=mergeDeletions(removedRegistry,d);persistDeletions();refreshCatalogGuards()}).catch(()=>{});
}

