 if(['surface','button','nav','input'].includes(t.kind))props.push(`border-radius:${Math.min(28,s.rounding)}px!important`);
 if(layers.length)props.push(`background-image:${layers.join(',')}!important`,`background-position:${s.imagePosition}!important`,`background-size:${s.imageSize}!important`,`background-repeat:${s.imageRepeat}!important`);
 if(['vscroll','hscroll'].includes(t.kind)){props.push(`background-color:${s.track}!important`);}
 out.push(`${sel}{${props.join(';')}}`);
