 if(t.kind==='text'||t.kind==='list'){props.push(...(s.fontSize!==defaultFor(t).fontSize?[`font-size:${Math.max(11,Math.min(t.id==='title'?44:30,s.fontSize))}px`]:[]),...(s.fontWeight!==defaultFor(t).fontWeight?[`font-weight:${s.fontWeight}`]:[]),...(s.fontStyle!==defaultFor(t).fontStyle?[`font-style:${s.fontStyle}`]:[]),...(s.textDecoration!==defaultFor(t).textDecoration?[`text-decoration:${s.textDecoration}`]:[]),...(s.textTransform!==defaultFor(t).textTransform?[`text-transform:${s.textTransform}`]:[]),...(s.letterSpacing!==defaultFor(t).letterSpacing?[`letter-spacing:${Math.max(-1,Math.min(4,s.letterSpacing))}px`]:[]),...(s.lineHeight!==defaultFor(t).lineHeight?[`line-height:${Math.max(1.15,Math.min(1.85,s.lineHeight))}`]:[]),...(s.textAlign!==defaultFor(t).textAlign?[`text-align:${s.textAlign}`]:[]))}
 if(t.kind==='text'||t.kind==='nav'||t.kind==='button'||t.kind==='surface'||t.kind==='outline'||t.kind==='background')props.push(`border-radius:${Math.min(24,s.rounding)}px`);
