function apply(){ $('#generatedDesignCSS').textContent=compileCSS();const canvas=$('#designStage');canvas.classList.toggle('show',state.showDemo);if(state.showDemo){$$('#designStage [data-design-target]').forEach(el=>el.classList.toggle('demo-selected',el.dataset.designTarget===state.selected))}const active=target();$('#designerBar small').textContent=active?`Editing ${active.label}`:'Choose or add a target';updateHistoryButtons()}
function sampleContent(t){const id=esc(t.id),name=esc(t.label);if(t.kind==='divider')return `<hr data-design-target="${id}"/>`;if(t.kind==='button')return `<button type="button" data-design-target="${id}">${name}</button>`;if(t.kind==='nav')return `<nav data-design-target="${id}">Home · Profile · Posts</nav>`;if(t.kind==='input')return `<input data-design-target="${id}" aria-label="${name}" placeholder="Sample input"/>`;if(t.kind==='list')return `<ul data-design-target="${id}"><li>First item</li><li>Second item</li></ul>`;if(t.kind==='hscroll'||t.kind==='vscroll')return `<div class="demo-scroll ${t.kind==='hscroll'?'horizontal':'vertical'}" data-design-target="${id}"><div>Scrollable sample for ${name} · Scroll to test the track and thumb colors.</div></div>`;if(t.kind==='background')return `<div data-design-target="${id}" style="min-height:54px">${name}</div>`;if(t.kind==='text'||t.kind==='outline')return `<div data-design-target="${id}">${name} · The quick brown fox</div>`;return `<div data-design-target="${id}">${name} · Sample surface</div>`}
function rebuildDemo(){const canvas=$('#designStage');const grouped=Object.groupBy?Object.groupBy(state.targets,t=>t.group):state.targets.reduce((o,t)=>((o[t.group]??=[]).push(t),o),{});canvas.innerHTML=`<div style="margin-bottom:10px;display:flex;gap:12px;align-items:center;justify-content:space-between;flex-wrap:wrap"><strong>Live sample page</strong><button type="button" id="hideStage" style="background:white;border:1px solid #cbd5df;border-radius:6px;padding:6px 10px">Hide preview</button></div>`+Object.entries(grouped).map(([group,ts])=>`<section><h2 style="font:650 18px/1.3 system-ui;margin-top:20px">${esc(group)}</h2><div class="demo-grid">${ts.filter(t=>t.id!=='website-background-image').map(t=>`<div class="demo-block">${sampleContent(t)}</div>`).join('')}</div></section>`).join('');$('#hideStage')?.addEventListener('click',()=>mutate(()=>{state.showDemo=false},'Sample page hidden'))}
