function statusCounts(){return `${state.targets.length} available areas · ${ALL_TARGETS.length} originals`}
function targetPickerMarkup(){const groups=['All',...new Set(state.targets.map(t=>t.group))];return `<div class="surface"><div class="labelled"><label for="targetFilter">Find target area</label><input id="targetFilter" type="search" placeholder="Search headings, scrollbars, Onyx…"></div><div class="pillset" id="groupPills" style="margin-top:8px">${groups.map(g=>`<button type="button" class="pill" data-group="${esc(g)}" aria-pressed="${String(g===selectedGroup)}">${esc(g)}</button>`).join('')}</div><div class="target-list" id="targetList" style="margin-top:9px"></div></div>`}
function renderTargetRows(){const q=String($('#targetFilter')?.value||'').toLowerCase();const list=$('#targetList');if(!list)return;list.innerHTML=state.targets.filter(t=>(selectedGroup==='All'||t.group===selectedGroup)&&(!q||`${t.label} ${t.group} ${t.selector}`.toLowerCase().includes(q))).map(t=>`<div class="target-row"><button type="button" class="target-pick" data-pick="${t.id}" aria-pressed="${String(state.selected===t.id)}">${esc(t.label)}<small>${esc(t.group)}</small></button><button type="button" class="ui small" data-jump="${t.id}" title="Jump to this area">↘</button></div>`).join('')||'<p>No matching areas. Add one below.</p>'}
function renderTargets(){const t=target();$('#view-targets').innerHTML=`<h2>Target navigator</h2><p>Jump to a page area or choose what to style. This combines the floating Jump Nav destinations with page-specific design roles.</p><div class="line"><button type="button" class="ui ${state.showDemo?'primary':''}" data-action="demo">${state.showDemo?'Hide sample page':'Show sample page'}</button><button type="button" class="ui" data-action="resetPosition">Reset bubble position</button></div>${targetPickerMarkup()}<div class="surface"><h3>Selected target</h3>${t?`<strong>${esc(t.label)}</strong><div class="labelled"><label for="selectorInput">Extra matching CSS selector (optional)</label><input id="selectorInput" value="${esc(t.selector)}" placeholder=".my-class, #my-id"><small class="subtle">Its built-in <code>data-design-target="${esc(t.id)}"</code> attribute always works. Extra selectors also match existing site sections.</small></div><div class="line" style="margin-top:8px"><button type="button" class="ui" data-action="saveSelector">Save selector</button><button type="button" class="ui primary" data-action="goStyle">Style this area</button><button type="button" class="ui danger" data-action="removeTarget">Remove area</button></div>`:'No areas yet; add one below.'}</div><details open><summary>Add a new target area</summary><div class="details-inner"><div class="grid2"><div class="labelled"><label for="newLabel">Area name</label><input id="newLabel" placeholder="Example: Bulletin heading"></div><div class="labelled"><label for="newKind">Element type</label><select id="newKind">${['surface','text','outline','divider','nav','button','input','list','hscroll','vscroll','background'].map(k=>`<option value="${k}">${k}</option>`).join('')}</select></div></div><div class="labelled"><label for="newSelector">CSS selector (optional)</label><input id="newSelector" placeholder=".bulletin-title"></div><div class="labelled"><label for="newGroup">Group name</label><input id="newGroup" value="Custom" maxlength="50"></div><button type="button" class="ui primary" data-action="addTarget">Add design area</button></div></details><div class="line"><button type="button" class="ui" data-action="restoreBuiltins">Restore missing original areas</button></div><p class="subtle">${statusCounts()}. Removing a target removes its settings; you can restore standard areas any time.</p>`;renderTargetRows()}
function colorRows(){const s=style();return Object.entries(COLOR_FIELDS).map(([k,label])=>`<div class="color-row"><label for="cl-${k}">${esc(label)}</label><input id="cl-${k}" aria-label="${esc(label)} color wheel" type="color" data-field="${k}" value="${s[k]}"><input class="hex" aria-label="${esc(label)} hex" data-hex="${k}" value="${s[k]}" spellcheck="false" maxlength="7"></div>`).join('')}
function options(obj,val){return Object.entries(obj).map(([l,v])=>`<option value="${esc(v)}"${String(val)===String(v)?' selected':''}>${esc(l)}</option>`).join('')}
function selectBox(label,k,values){return `<div class="labelled"><label>${esc(label)}<select data-field="${k}">${options(values,style()[k])}</select></label></div>`}
function range(label,k,min,max,step=1,unit=''){let v=style()[k];return `<div class="labelled"><div class="control-head"><label>${esc(label)}</label><output data-output="${k}">${v}${unit}</output></div><input aria-label="${esc(label)}" type="range" data-field="${k}" min="${min}" max="${max}" step="${step}" value="${v}"></div>`}
function preview(){const t=target();if(!t)return '';return `<div class="surface"><div class="line"><strong class="grow">Live preview · ${esc(t.label)}</strong><button type="button" class="ui small" data-action="jumpTo">Jump ↘</button></div><div class="mini-preview">${sampleContent(t)}</div><p class="subtle">Hover to test interactive colors; select “Show sample page” to see the complete layout.</p></div>`}
function renderStyle(){const t=target();if(t?.id.startsWith('pm-')&&window.OurSpaceProfileModuleDesign){const part=window.OurSpaceProfileModuleDesign.byTarget(t.id);if(part){$('#view-style').innerHTML=window.OurSpaceProfileModuleDesign.renderControl(t.id,state.profileModuleParts?.[part.mod.id]?.[part.part.id],esc);return}}if(t?.id.startsWith('lm-')&&window.OurSpaceLinksModuleDesign){const part=window.OurSpaceLinksModuleDesign.byTarget(t.id);if(part){$('#view-style').innerHTML=window.OurSpaceLinksModuleDesign.renderControl(t.id,state.linksParts?.[part.id],esc);return}}if(t?.id.startsWith('bb-')&&window.OurSpaceBulletinDesign){const part=window.OurSpaceBulletinDesign.byTarget(t.id);if(part){$('#view-style').innerHTML=window.OurSpaceBulletinDesign.renderControl(t.id,state.bulletinParts?.[part.id],esc);return}}if(t?.id.startsWith('rp-')&&window.OurSpaceRecordPlayerDesign){const part=window.OurSpaceRecordPlayerDesign.byTarget(t.id);if(part){$('#view-style').innerHTML=window.OurSpaceRecordPlayerDesign.renderControl(t.id,state.recordParts?.[part.id],esc);return}}if(!t){$('#view-style').innerHTML='<h2>No selected target</h2><p>Add an area in Targets.</p>';return}const s=style();$('#view-style').innerHTML=`<div class="line"><div class="grow"><h2>Design · ${esc(t.label)}</h2><p>Live changes affect only matching targets.</p></div><button type="button" class="ui small" data-action="resetTarget">Reset</button></div><div class="labelled"><label for="quickTarget">Switch target</label><select id="quickTarget">${state.targets.map(a=>`<option value="${a.id}"${a.id===t.id?' selected':''}>${esc(a.label)}</option>`).join('')}</select></div>${preview()}<details open><summary>Color studio · color wheels + hex</summary><div class="details-inner">${colorRows()}<div class="line"><label for="presetSwatch">Quick swatch</label><select id="presetSwatch" class="grow">${options(PREMADE_SWATCHES,'')}</select><button type="button" class="ui small" data-action="applySwatch">Apply to fill</button></div></div></details><details><summary>Fonts and lettering</summary><div class="details-inner">${selectBox('Font family','font',FONTS)}<div class="grid2">${selectBox('Weight','fontWeight',{'Light':'300','Regular':'400','Medium':'500','Semi bold':'600','Bold':'700','Heavy':'750','Extra bold':'800','Black':'900'})}${selectBox('Text align','textAlign',{'Left':'left','Center':'center','Right':'right','Justify':'justify'})}${selectBox('Font style','fontStyle',{'Normal':'normal','Italic':'italic'})}${selectBox('Decoration','textDecoration',{'None':'none','Underline':'underline','Strike':'line-through','Overline':'overline'})}</div>${selectBox('Letter case','textTransform',{'Keep original':'none','UPPERCASE':'uppercase','lowercase':'lowercase','Title Case':'capitalize'})}${range('Font size','fontSize',8,100,1,'px')}${range('Line height','lineHeight',.85,3,.05,'×')}${range('Letter spacing','letterSpacing',-4,20,.5,'px')}${range('Text border / stroke','textStrokeWidth',0,3,.1,'px')}<div class="color-row"><label for="textStrokeColor">Text border color</label><input type="color" id="textStrokeColor" data-field="textStrokeColor" value="${s.textStrokeColor}"><input data-hex="textStrokeColor" class="hex" value="${s.textStrokeColor}"></div></div></details><details><summary>Borders, space and shadows</summary><div class="details-inner"><div class="grid2">${selectBox('Border style','borderStyle',{'None':'none','Solid':'solid','Dashed':'dashed','Dotted':'dotted','Double':'double','Groove':'groove','Ridge':'ridge','Inset':'inset','Outset':'outset'})}${range('Border width','borderWidth',0,20,1,'px')}</div>${range('Corners','rounding',0,80,1,'px')}${range('Inner padding','padding',0,70,1,'px')}${range('Child spacing','gap',0,50,1,'px')}${range('Opacity','opacity',10,100,1,'%')}${range('Shadow depth','shadowSize',0,24,1,'px')}${range('Shadow blur','shadowBlur',0,50,1,'px')}</div></details><details><summary>Scrollbar tuning</summary><div class="details-inner">${range('Scrollbar width / height','scrollbarSize',4,30,1,'px')}<p>Track, thumb and hover colors use the color wheels above, including the four numbered scrollbar areas.</p></div></details><details><summary>Readability</summary><div class="details-inner"><div id="contrastReport"></div><button type="button" class="ui" data-action="repairContrast">Repair text contrast</button></div></details>`;updateContrast()}

