const IMAGE_LIBRARY=RAW_IMAGE_LIBRARY.filter(x=>!isRemoved('images',x));
const IMAGE_CATEGORIES=['Aesthetics & Styles','Colors & Color Preferences','Themes & General Interests','Music','Movies & Television','Video Games','Real Life'];
const IMAGE_PER_PAGE=8;
let imageCategory='',imageSubcategory='All',imageSearch='',imagePage=0,previewImageId='',imageTabPrimed=false;
function imageMatches(){
 if(!imageCategory)return [];
 return IMAGE_LIBRARY.filter(item=>item.category===imageCategory&&(imageSubcategory==='All'||item.subcategory===imageSubcategory)&&(!imageSearch||`${item.title} ${item.subcategory}`.toLowerCase().includes(imageSearch)));
}
function imageThumbURL(url){if(/drive\.google\.com\/thumbnail\?/.test(url))return url.replace(/([?&])sz=w\d+/, '$1sz=w360');return url+(url.includes('?')?'&':'?')+'width=360'}
function imageLibraryResults(){
 if(!imageCategory)return '';
 const matching=imageMatches(),pageCount=Math.max(1,Math.ceil(matching.length/IMAGE_PER_PAGE));imagePage=Math.min(Math.max(0,imagePage),pageCount-1);
 const start=imagePage*IMAGE_PER_PAGE,visible=matching.slice(start,start+IMAGE_PER_PAGE);
 const cards=visible.map(item=>{
   const active=previewImageId===item.id;
   return `<article class="image-asset-card${active?' is-previewing':''}"><div class="image-asset-thumb"><img src="${esc(item.thumbnail||imageThumbURL(item.url))}" loading="lazy" decoding="async" fetchpriority="low" alt="${esc(item.title)}" referrerpolicy="no-referrer" onerror="this.hidden=true;this.nextElementSibling.hidden=false"><span class="image-asset-fallback" hidden>Preview unavailable</span></div><strong>${esc(item.title)}</strong><small>${esc(item.subcategory)}</small><div class="image-asset-actions"><button type="button" class="ui small${active?' current':''}" data-image-preview="${item.id}" aria-label="Preview ${esc(item.title)} on selected page area">${active?'Previewing':'Preview on page'}</button><a class="image-asset-license" href="${esc(item.license)}" target="_blank" rel="noopener noreferrer">${item.sourceType==='google-drive'?'View original on Google Drive ↗':'File + license ↗'}</a></div></article>`
 }).join('');
 return `<p class="subtle">${matching.length} matches · Showing ${matching.length?start+1:0}–${Math.min(matching.length,start+IMAGE_PER_PAGE)}. Only eight thumbnails are created at once.</p><div class="image-asset-grid">${cards||'<p>No images match this filter.</p>'}</div><div class="line image-asset-pages"><button type="button" class="ui" data-action="imagePrev" ${imagePage===0?'disabled':''}>Previous</button><span>Page ${imagePage+1} / ${pageCount}</span><button type="button" class="ui" data-action="imageNext" ${imagePage>=pageCount-1?'disabled':''}>Next</button></div>`;
}
function imageLibraryMarkup(){
 const chosen=imageCategory;
 const categories=`<div class="image-category-grid">${IMAGE_CATEGORIES.map((cat,i)=>`<button type="button" class="image-category-button${chosen===cat?' chosen':''}" data-image-category="${esc(cat)}" aria-pressed="${String(chosen===cat)}"><strong>${i+1}. ${esc(cat)}</strong><small>${IMAGE_LIBRARY.filter(item=>item.category===cat).length} images</small></button>`).join('')}</div>`;
 if(currentTab!=='images')return '<section id="backgroundLibrary"><h3>Browse image collection</h3></section>';
 const subs=chosen?[...new Set(IMAGE_LIBRARY.filter(item=>item.category===chosen).map(item=>item.subcategory))]:[];
 return `<section class="surface image-library" id="backgroundLibrary"><h3>Browse 121 background image links</h3><p>Pick a category first. Images are only requested for the eight items on the current page, with names and source/license links from your supplied collection.</p>${categories}${chosen?`<div class="line image-library-heading"><strong class="grow">${esc(chosen)}</strong><button type="button" class="ui small" data-action="imageClearCategory">Back to categories</button></div><div class="grid2"><div class="labelled"><label for="imageSubcategory">Interest / subcategory</label><select id="imageSubcategory"><option value="All">All interests</option>${subs.map(sub=>`<option value="${esc(sub)}" ${imageSubcategory===sub?'selected':''}>${esc(sub)}</option>`).join('')}</select></div><div class="labelled"><label for="imageFind">Search these images</label><input type="search" id="imageFind" value="${esc(imageSearch)}" placeholder="Image or interest name"></div></div><div id="imageLibraryResults">${imageLibraryResults()}</div>`:'<p class="subtle">Choose one of the six categories to load image previews.</p>'}<p class="subtle">Wikimedia Commons files have individual reuse licenses. Personal Google Drive photos remain hosted in Drive and are not packaged. Confirm sharing permissions before public use; images of people and media franchises may have additional rights.</p></section>`;
}
function imageRefreshResults(){if(currentTab!=='images')return;const holder=$('#imageLibraryResults');if(holder)holder.innerHTML=imageLibraryResults();}
function applyImagePreview(id){
 const entry=IMAGE_LIBRARY.find(item=>item.id===id&&!isRemoved('images',item));
 if(!entry||entry.category!==imageCategory||!style())return;
 if(!previewBefore)previewBefore=clone(state);
 previewImageId=id;previewPresetId='';state.styles[state.selected].image=entry.url;
 apply();updatePreviewUI();renderImages();notify('Previewing image: '+entry.title+' · Keep or Undo before leaving.');
}

function renderImages(){const t=target();if(!t){$('#view-images').innerHTML='<h2>No target selected</h2>';return}const s=style();$('#view-images').innerHTML=`<h2>Wallpapers and background images</h2><p>Website wallpaper, module backgrounds 1–4, and any other target can each have independent images, layouts and image settings.</p><div class="labelled"><label for="imageTarget">Image target</label><select id="imageTarget">${state.targets.map(x=>`<option value="${x.id}"${x.id===t.id?' selected':''}>${esc(x.label)}</option>`).join('')}</select></div><div class="surface"><strong>${esc(t.label)}</strong><div class="labelled"><label for="imageUrl">Image URL (https://, http:// or uploaded data)</label><textarea id="imageUrl" rows="2" placeholder="https://example.com/wallpaper.png">${s.image.startsWith('data:')?'':esc(s.image)}</textarea></div><div class="line"><button type="button" class="ui primary" data-action="applyImageURL">Use image link</button><button type="button" class="ui danger" data-action="clearImage">Remove image</button></div><div class="labelled" style="margin-top:10px"><label for="imageUpload">Upload from device (embedded in saved HTML)</label><input id="imageUpload" type="file" accept="image/png,image/jpeg,image/webp,image/gif,image/avif"></div><div class="mini-preview" id="imageSample" style="min-height:150px;background-size:cover;background-position:center">${s.image?`<img src="${esc(s.image)}" alt="Selected background" style="max-height:130px;max-width:100%;object-fit:contain;margin:auto">`:'<span>No background image selected</span>'}</div></div><details open><summary>Image fit and placement</summary><div class="details-inner"><div class="grid2">${selectBox('Sizing','imageSize',{'Fill / crop':'cover','Contain / entire image':'contain','Natural':'auto','Stretch':'100% 100%'})}${selectBox('Repeat','imageRepeat',{'No repeat':'no-repeat','Tile':'repeat','Tile horizontally':'repeat-x','Tile vertically':'repeat-y'})}${selectBox('Position','imagePosition',{'Top left':'left top','Top middle':'center top','Top right':'right top','Middle left':'left center','Center':'center center','Middle right':'right center','Bottom left':'left bottom','Bottom middle':'center bottom','Bottom right':'right bottom'})}${selectBox('Attachment','imageAttachment',{'Scroll with page':'scroll','Fixed wallpaper':'fixed','Local to container':'local'})}</div><div class="details-inner"><h4>Artwork overlay and texture</h4><div class="color-row"><label for="overlayColor">Overlay tint</label><input id="overlayColor" type="color" data-field="overlayColor" value="${s.overlayColor}"><input class="hex" data-hex="overlayColor" value="${s.overlayColor}"></div>${range('Overlay opacity','overlayOpacity',0,95,1,'%')}${selectBox('Decorative pattern','pattern',{'None':'none','Subtle dots':'dots','Fine stripes':'stripes','Grid':'grid'})}</div></details><p class="subtle">Local uploads are reduced to browser-friendly sizes where possible. Very large projects should be exported as JSON or as a complete HTML file.</p>${imageLibraryMarkup()}`}
function presetButtons(){return state.presets.map((p,i)=>{const s=p.data?.styles?.[p.data?.selected]||p.data?.styles?.title||{};return `<button type="button" class="preset-slot" data-slot="${i}" aria-pressed="${String(state.activePreset===i)}"><strong>${esc(p.name)}</strong><div class="swatches">${['text','bg','border','accent'].map(k=>`<i style="--s:${hexOk(s[k])?s[k]:'#F8FAFC'}"></i>`).join('')}</div>${p.data?'Saved':'Empty'}</button>`}).join('')}
function renderLooks(){const p=state.presets[state.activePreset];$('#view-looks').innerHTML=`<h2>Saved looks and layout themes</h2><p>Six personal saved looks plus starter color palettes. The separate 100 Presets tab contains archive-linked layout interpretations. Your original saved looks remain editable.</p><h3>One-click palettes</h3><div class="pillset">${[['classic','Classic blue'],['retro','Retro pastel'],['neon','Neon scene'],['vintage','Vintage paper'],['midnight','Midnight'],['rainbow','Rainbow accents']].map(([k,v])=>`<button type="button" class="ui small" data-theme="${k}">${v}</button>`).join('')}</div><h3>Saved looks</h3><div class="preset-grid">${presetButtons()}</div><div class="surface"><div class="labelled"><label for="lookName">Look name</label><input id="lookName" value="${esc(p.name)}" maxlength="35"></div><div class="line" style="margin-top:8px"><button type="button" class="ui primary" data-action="saveLook">Save current</button><button type="button" class="ui" data-action="applyLook" ${p.data?'':'disabled'}>Apply</button><button type="button" class="ui" data-action="renameLook">Rename</button><button type="button" class="ui danger" data-action="clearLook">Clear</button></div></div><h3>Apply a look elsewhere</h3><div class="surface"><p>Compatible styles transfer by matching target ID and element type. Profile-only modules do not transfer to unrelated widgets.</p><div class="labelled"><label for="copyTargetPage">Destination page</label><select id="copyTargetPage">${['profile','household','journal','diary','feed','skills','communication','audio','visual','store'].filter(v=>v!==contextPage).map(v=>`<option value="${v}">${v[0].toUpperCase()+v.slice(1)}</option>`).join('')}</select></div><div class="line" style="margin-top:8px"><button type="button" class="ui" data-action="copySelected">Copy selected target</button><button type="button" class="ui" data-action="copyCompatible">Copy compatible design</button><button type="button" class="ui primary" data-action="copySitewide">Apply common styles site-wide</button></div></div><h3>Canvas and recovery</h3><div class="line"><button type="button" class="ui" data-action="demo">${state.showDemo?'Hide':'Show'} sample page</button><button type="button" class="ui danger" data-action="resetAll">Reset entire design</button></div><p class="subtle">Changes are saved on this browser. Export a JSON backup or full standalone HTML for a portable copy.</p>`}
function renderExport(){const css=compileCSS();$('#view-export').innerHTML=`<h2>Export and integration</h2><p>Export CSS to apply styles to real OurSpace or MySpace-inspired markup. To target a section precisely, give it <code>data-design-target="target-id"</code> or set a matching selector in Targets.</p><div class="line"><button type="button" class="ui primary" data-action="downloadHTML">Download standalone HTML</button><button type="button" class="ui" data-action="downloadJSON">Export JSON</button><button type="button" class="ui" data-action="importJSON">Import JSON</button><input id="importFile" type="file" accept=".json,application/json" hidden></div><h3>Generated CSS</h3><div class="line"><button type="button" class="ui" data-action="downloadCSS">Download CSS</button><button type="button" class="ui" data-action="copyCSS">Copy CSS</button></div><textarea readonly id="cssPreview" spellcheck="false" rows="8" style="margin-top:8px;font-size:11px!important;font-family:ui-monospace,monospace!important">${esc(css)}</textarea><h3>Sample integration HTML</h3><textarea readonly id="integrationPreview" spellcheck="false" rows="4" style="font-size:11px!important;font-family:ui-monospace,monospace!important">${esc(`<h1 data-design-target="title">My page title</h1>\n<nav data-design-target="nav-menu-1">Home · About</nav>\n<button data-design-target="buttons-1">Action</button>\n<div data-design-target="module-background-image-1">Content</div>`)}</textarea><p class="subtle">The standalone file contains the logo, CSS, editor code and design state. Exported CSS works in a standard DOM, with no iframe, Shadow DOM, builder or runtime required.</p>`}
function render(){renderTargets();renderStyle();renderImages();renderLooks();renderExport();switchTab(currentTab,false);updateHistoryButtons()}
function switchTab(tab,focus){if(galleryPending()&&tab!==(previewImageId?'images':'gallery')){notify('Choose Keep or Undo before switching designer tabs.');return;}currentTab=tab;$$('#designerTabs [data-view]').forEach(el=>el.setAttribute('aria-selected',String(el.dataset.view===tab)));$$('#designerBody .view').forEach(el=>el.classList.toggle('active',el.id===`view-${tab}`));$('#designerBody').scrollTop=0;if(tab==='gallery')renderGallery();if(tab==='images'){if(!imageTabPrimed){imageTabPrimed=true;if(state.selected==='title'&&state.targets.some(t=>t.id==='website-background-image'))state.selected='website-background-image';}renderImages();}if(focus)$(`#designerTabs [data-view="${tab}"]`)?.focus()}
function selectTarget(id,nextTab){if(!state.targets.some(t=>t.id===id))return;state.selected=id;persist();render();apply();if(nextTab)switchTab(nextTab);notify('Selected '+target().label)}
function luminance(hex){const c=[1,3,5].map(i=>parseInt(hex.slice(i,i+2),16)/255).map(v=>v<=.04045?v/12.92:((v+.055)/1.055)**2.4);return c[0]*.2126+c[1]*.7152+c[2]*.0722}
function contrast(a,b){let x=luminance(a),y=luminance(b);return (Math.max(x,y)+.05)/(Math.min(x,y)+.05)}
function updateContrast(){const e=$('#contrastReport'),s=style();if(!e||!s)return;const r=contrast(s.text,s.bg);e.className=r>=4.5?'ok':'error';e.textContent=`Text/background contrast: ${r.toFixed(2)}:1 · ${r>=4.5?'passes AA normal text':'below AA normal-text target (4.5:1)'}.`;}
const palettes={classic:['#FFFFFF','#163A6D','#DBE8FD','#7A9BC8','#EFF5FF'],retro:['#FFFAF2','#4D2441','#FFE8F3','#FF67AE','#FFF3DB'],neon:['#141021','#F9FDFF','#372C58','#00F5D4','#281E43'],vintage:['#F6EBD2','#503E2C','#E3D3AF','#9F7050','#EFE0C3'],midnight:['#0B1621','#EDF6FA','#20384A','#6DCEF1','#193046'],rainbow:['#FFFFFF','#17152D','#ECF9FC','#ED4C8B','#E4FEF5']};
function applyTheme(id){const pal=palettes[id];if(!pal)return;mutate(()=>{for(const t of state.targets){let s=state.styles[t.id];s.text=pal[1];s.bg=(t.id==='website-background-image'?pal[0]:['surface','nav','button','background','input'].includes(t.kind)?pal[2]:pal[0]);s.border=pal[3];s.accent=pal[3];s.hover=pal[4];s.hoverText=pal[1];s.outline=pal[3];s.track=pal[2];s.thumb=pal[3];s.thumbHover=pal[1];}if(id==='rainbow'){let j=0;const rainbow=['#E9454F','#FF8A00','#FAC929','#51BC58','#14C9BD','#227BEA','#A252D8','#EC43B6'];for(const t of state.targets){state.styles[t.id].accent=rainbow[j++%rainbow.length];state.styles[t.id].border=rainbow[j%rainbow.length]}}},'Applied '+id+' palette to all areas')}

