function galleryMatches(){if(!galleryCategory)return [];return GALLERY_CATALOG.filter(p=>p.browseCategory===galleryCategory&&(!gallerySearch||`${p.title} ${p.category} ${p.id}`.toLowerCase().includes(gallerySearch)))}
