function renderGallery(){const container=$('#view-gallery');if(!container)return;
 const counts=Object.fromEntries(BROWSE_CATEGORIES.map(c=>[c,GALLERY_CATALOG.filter(p=>p.browseCategory===c).length]));
 const choose=`<div class="gallery-category-grid">${BROWSE_CATEGORIES.map((c,i)=>`<button type="button" class="gallery-category-button${galleryCategory===c?' chosen':''}" data-gallery-category="${esc(c)}" aria-pressed="${String(galleryCategory===c)}"><strong>${i+1}. ${esc(c)}</strong><small>${esc(CATEGORY_HINTS[c])}</small><span>${counts[c]} presets</span></button>`).join('')}</div>`;
 container.innerHTML=`<h2>Browse MySpace layout presets</h2><p>Choose one of six categories first. Only one category and eight thumbnails per page load at a time. Select a preset to preview it directly on this profile, then choose <strong>Keep</strong> or <strong>Undo</strong>.</p>${choose}${galleryCategory?`<div class="surface gallery-active-category"><div class="line"><strong class="grow">${esc(galleryCategory)}</strong><button type="button" class="ui small" data-action="galleryClearCategory">Change category</button></div><div class="labelled"><label for="galleryFind">Find a preset in this category</label><input id="galleryFind" type="search" placeholder="Search these ${counts[galleryCategory]} presets" value="${esc(gallerySearch)}"></div></div><div id="galleryResults">${galleryGrid()}</div><div id="gallerySelectedDetails">${galleryDetails(GALLERY_CATALOG.find(x=>x.id===gallerySelected&&x.browseCategory===galleryCategory))}</div>`:'<p class="subtle">No thumbnails have been loaded. Pick a category to begin.</p>'}`;
 updatePreviewUI();
}
function galleryRefreshGrid(){if(currentTab!=='gallery')return;const a=$('#galleryResults');if(a)a.innerHTML=galleryGrid();const b=$('#gallerySelectedDetails');if(b)b.innerHTML=galleryDetails(GALLERY_CATALOG.find(x=>x.id===gallerySelected&&x.browseCategory===galleryCategory));updatePreviewUI()}

function download(content,filename,type='text/plain'){const blob=new Blob([content],{type});const url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=filename;document.body.append(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),5000)}
function exportPayload(){const s=clone(state);for(const p of s.presets)if(p.data&&JSON.stringify(p.data).length>15000000)p.data=null;return {schema:'ourspace.design-widget.v1',exportedAt:new Date().toISOString(),...s}}
