async function handleImageFile(file){if(!file||!file.type.startsWith('image/'))return notify('Choose an image file.',true);try{const data=await new Promise((resolve,reject)=>{const reader=new FileReader();reader.onload=()=>resolve(reader.result);reader.onerror=reject;reader.readAsDataURL(file)});const img=new Image();img.src=data;await img.decode();const ratio=Math.min(1,1600/Math.max(img.width,img.height));const c=document.createElement('canvas');c.width=Math.round(img.width*ratio);c.height=Math.round(img.height*ratio);c.getContext('2d').drawImage(img,0,0,c.width,c.height);const encoded=c.toDataURL('image/webp',.86);mutate(()=>{style().image=safeURL(encoded)},`Uploaded image to ${target().label}`)}catch(e){notify('Could not load that image.',true)}}
function designRailLeft(){const rail=document.querySelector('#sidebar-messenger-root .mp-sidebar.mp-vertical-menu');const r=rail?.getBoundingClientRect();if(r&&r.width>40)return r.left;const css=getComputedStyle(document.documentElement);return innerWidth-(parseFloat(css.getPropertyValue('--os-sidebar-width'))||Math.min(300,innerWidth*.25))-(parseFloat(css.getPropertyValue('--os-sidebar-right'))||0)}
