function openPanel(){const b=$('#designerBubble'),r=b.getBoundingClientRect(),p=$('#designerPanel');b.hidden=true;p.hidden=false;p.style.width='';p.style.height='';const panelWidth=Math.min(470,innerWidth-16);const x=r.left+104+panelWidth<=innerWidth?r.left+104:r.left-panelWidth-8;movePanelTo(x,Math.max(8,Math.min(r.top,innerHeight-Math.min(790,innerHeight-30)-8)));$('#designerClose').focus()}
