function makeDraggable(el,handle,onClick,onEnd){let active=null;handle.addEventListener('pointerdown',e=>{if(e.button!==0||e.target.closest('button')&&e.target!==handle)return;const r=el.getBoundingClientRect();active={pointer:e.pointerId,x:e.clientX,y:e.clientY,left:r.left,top:r.top,moved:false};handle.setPointerCapture(e.pointerId)});handle.addEventListener('pointermove',e=>{if(!active||e.pointerId!==active.pointer)return;const dx=e.clientX-active.x,dy=e.clientY-active.y;if(Math.hypot(dx,dy)>5)active.moved=true;if(!active.moved)return;if(el.id==='designerPanel')movePanelTo(active.left+dx,active.top+dy);else positionBubble(active.left+dx,active.top+dy)});handle.addEventListener('pointerup',e=>{if(!active||e.pointerId!==active.pointer)return;const moved=active.moved;active=null;try{handle.releasePointerCapture(e.pointerId)}catch(_){}if(moved){onEnd?.()}else onClick?.()});handle.addEventListener('pointercancel',()=>{active=null})}
